changeSet.sql:
CREATE TABLE auth_session (
 id UUID PRIMARY KEY,
 user_id BIGINT NOT NULL REFERENCES own_user(id) ON DELETE CASCADE,
 created_at TIMESTAMPTZ NOT NULL,
 last_rotated_at TIMESTAMPTZ NOT NULL,
 expires_at TIMESTAMPTZ NOT NULL,
 revoked_at TIMESTAMPTZ,
 user_agent VARCHAR(255) NOT NULL
);
CREATE INDEX idx_auth_session_user_created ON auth_session(user_id,created_at DESC);
ALTER TABLE refresh_token ADD COLUMN session_id UUID REFERENCES auth_session(id) ON DELETE CASCADE;
CREATE INDEX idx_refresh_token_session ON refresh_token(session_id);
